    ) ?? null;

  if (status === "not_measured" && score !== null) {
    fail(
      "inconsistent",
      joinPath(path, "score"),
      'dimensão não avaliada não pode ter nota (pronúncia sem áudio é "não avaliada")',
    );
  }
  if (status !== "not_measured" && score === null) {
    fail("inconsistent", joinPath(path, "score"), `dimensão com status "${status}" exige nota`);
