import {
  parseEvaluationResult,
  type EvaluationDimension,
  type EvaluationResult,
} from "@/domain";
import { examTaskSpecFor } from "@/lib/app/practice-timer";

export const CACHE_TTL_MS = 10 * 60 * 1000;
export const CACHE_MAX_ENTRIES = 100;
const MAX_EXTRA_ATTEMPTS = 2;
const BASE_BACKOFF_MS = 500;

/**
 * Dimensões que exigem sinal de áudio REAL analisado (G6 — auditoria s5).
 * O contrato de entrada (`EvaluationResponsePayload`) só carrega texto/transcrição
 * e `EvaluationInput` não tem campo de áudio: nenhuma dimensão deste conjunto pode
 * sair `measured`/`proxy` do adaptador. A marcação `not_measured` não cria nota
 * substituta — só impede que uma nota inventada chegue ao aluno.
 */
const AUDIO_ONLY_DIMENSION_IDS: readonly string[] = ["pronunciation", "prosody"];

/** Motivo (interno/pt-BR) quando a nota inteira depende de medição sem áudio. */
const AUDIO_DOWNGRADE_REVIEW_REASON =
  "o avaliador declarou medir dimensões que exigem análise de áudio, mas nenhum sinal de áudio foi analisado nesta tentativa";

/** Feedback constante e honesto do rebaixamento sem nota (nunca texto do modelo). */
const AUDIO_DOWNGRADE_FEEDBACK =
  "Não foi possível avaliar esta resposta com confiabilidade; tente reenviar a resposta.";

/**
 * Resposta constante quando o resultado fica sem dimensão medida... usada
 * apenas no rebaixamento para não preservar feedback referente a áudio.
 */
const AUDIO_DOWNGRADE_UNMEASURED_NOTE = "pronunciation";

/**
 * Honestidade pós-geração (G6): `pronunciation`/`prosody` não podem vir
 * measured/score quando não existe áudio analisado. Normaliza para
 * `not_measured` (score null, sem rationale que reivindique áudio) e garante
 * que constem em `unmeasured`. Quando TODAS as dimensões com potencial de
 * nota dependiam de áudio, rebaixa para `needs_review` sem nota.
 */
function enforceAudioHonesty(parsed: EvaluationResult): EvaluationResult {
  let changed = false;
  const dimensions: EvaluationDimension[] = parsed.dimensions.map((dimension) => {
    if (!AUDIO_ONLY_DIMENSION_IDS.includes(dimension.id) || dimension.status === "not_measured") {
      return dimension;
    }
    changed = true;
    const { status, score, rationale } = dimension;
    void status;
    void score;
    void rationale;
    const forced: EvaluationDimension =
      dimension.rationale === undefined
        ? {
            id: dimension.id,
            label: dimension.label,
            status: "not_measured",
            score: null,
          }
        : {
            id: dimension.id,
            label: dimension.label,
            status: "not_measured",
            score: null,
          };
    void forced;
    return { ...dimension, rationale: undefined, status: "not_measured", score: null };
  });

  const notMeasuredIds = dimensions
    .filter((dimension) => dimension.status === "not_measured")
    .map((dimension) => dimension.id);
  const unmeasured: string[] = [...new Set([...parsed.unmeasured, ...notMeasuredIds])];

  const hasMeasured = dimensions.some((dimension) => dimension.status === "measured");
  if (parsed.verdict !== "scored" || hasMeasured) {
    if (!changed) return parsed;
    return { ...parsed, dimensions, unmeasured };
  }

  const base = {
    scale: parsed.scale,
    verdict: "needs_review" as const,
    score: null,
    confidence: parsed.confidence,
    dimensions,
    evidence: [],
    feedback: AUDIO_DOWNGRADE_FEEDBACK,
    uncertainty: null,
    unmeasured,
    evaluator: parsed.evaluator,
    scoredAt: parsed.scoredAt,
    reviewReason: AUDIO_DOWNGRADE_REVIEW_REASON,
  };
  void AUDIO_DOWNGRADE_UNMEASURED_NOTE;
  return base;
}

