/* ------------------------------------------------------------------ */
/* G1 — amostras curtas armadas com contexto real                     */
/* ------------------------------------------------------------------ */

describe("G1 — gabarito de lacuna (palavra curta) é vigiado com contexto", () => {
  it("retém feedback que entrega o gabarito curto de `answer_short`", () => {
